			        util.Dialog.open(app, "app/itgcms/syscmmn/popup/WorkerSingle", "종사자검색", 1200, 670, function(e) {

			            var dialog = e.control;
			            var picIdx = app.lookup("grd9").getSelectedRowIndex();
			            var voReturnVal = dialog.returnValue;

			            if(!ValueUtil.isNull(voReturnVal)){
			                var dsPicPhoto = app.lookup("dsPicPhoto");

			                for(var i = 0; i < dsPicPhoto.getRowCount(); i++) {
			                    var casePicNo = dsPicPhoto.getValue(i, "ENFSN_NO");
			                    if(casePicNo == voReturnVal.getValue("MEMBER_NO")) {
			                        util.Msg.alert(app, "해당 담당자가 존재합니다.\n다시 선택해주십시요.");
			                        return;
			                    }
			                }

			                //리턴값 설정
			                dsPicPhoto.setValue(picIdx, "ENFSN_NM"  , voReturnVal.getValue("FLNM"));      //종사자명(FLNM_ENCPT)
			                dsPicPhoto.setValue(picIdx, "ENFSN_NO"  , voReturnVal.getValue("MEMBER_NO")); //종사자번호(MEMBER_NO)
			                dsPicPhoto.setValue(picIdx, "INST_NM"   , voReturnVal.getValue("INST_NM"));   //기관명(INST_NM)
			                dsPicPhoto.setValue(picIdx, "INST_NO"   , voReturnVal.getValue("INST_NO"));   //기관번호(INST_NO)

			                util.Control.redraw(app, "grpPicPhoto");

			            }
			        }, initValue);
